head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnUseEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 useEditFormat 속성값을 반환합니다.",
    "validation" : [
        "Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 가지며 해당 인덱스/ID 로 useEditFormat 속성값을 조회할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Row 가 2줄(MultiLine) 로 구성된 그리드. 1줄=calDate1(calendar useEditFormat=true, 고유 인덱스 0)/txt1(text, 1), 2줄=calDate2(calendar useEditFormat=false, 고유 인덱스 2)/txt2(text, 3). MultiLine 이어도 2줄의 calDate2 는 인덱스 1 이 아니라 고유 인덱스 2 로 조회됨.\n[절차] columnInfo(인덱스/ID) 선택 후 (getColumnUseEditFormat 실행) 클릭.\n[확인] 0=true / 2=false(고유 인덱스 2) / calDate2(ID)=false(인덱스 2와 동일) / 99=false(유효하지않음) 가 반환영역에 boolean 으로 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="calDate1" name="calDate1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txt1" name="txt1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calDate2" name="calDate2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txt2" name="txt2" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "calDate1": "20260101", "txt1": "노트북", "calDate2": "20260201", "txt2": "블랙" },
        { "calDate1": "20260102", "txt1": "모니터", "calDate2": "20260202", "txt2": "화이트" },
        { "calDate1": "20260103", "txt1": "키보드", "calDate2": "20260203", "txt2": "실버" },
        { "calDate1": "20260104", "txt1": "마우스", "calDate2": "20260204", "txt2": "그레이" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 : Row 를 2줄(MultiLine) 로 구성
    //  - 1줄 : calDate1(고유 인덱스 0) / txt1(1)
    //  - 2줄 : calDate2(고유 인덱스 2) / txt2(3)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)와 고유 ID 를 가짐
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnUseEditFormat 테스트 그리드(MultiLine)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="240" style="" inputType="text" id="hcol1" value="일자1(calendar useEditFormat=true)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="품목(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="240" style="" inputType="text" id="hcol3" value="일자2(calendar useEditFormat=false)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="색상(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : calDate1 (calendar, useEditFormat=true)
    strTarget += '<w2:column width="240" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" useEditFormat="true" id="calDate1" dataList="calDate1"></w2:column>';
    // index 1 : txt1 (text)
    strTarget += '<w2:column width="*" style="" inputType="text" id="txt1" dataList="txt1"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : calDate2 (calendar, useEditFormat=false) - MultiLine 2줄 고유 인덱스 2, 고유 ID
    strTarget += '<w2:column width="240" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" useEditFormat="false" id="calDate2" dataList="calDate2"></w2:column>';
    // index 3 : txt2 (text)
    strTarget += '<w2:column width="*" style="" inputType="text" id="txt2" dataList="txt2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnUseEditFormat 조회 (MultiLine 고유 인덱스/ID 기반)
//  - Row 가 2줄(MultiLine) 이어도 모든 Column 은 고유 인덱스(0~3)와 고유 ID 를 가짐
//  - 2줄의 calDate2 는 인덱스 1 이 아니라 고유 인덱스 2 로 조회됨 (ID 'calDate2' 도 동일 결과)
//  - 0=true / 2=false / 'calDate2'=false / 99=false (모두 boolean)
scwin.btn_getColumnUseEditFormat_onclick = function () {
    let raw = par_columnInfo.getValue();
    // 숫자면 인덱스(Number), 아니면 컬럼 ID(문자열) 로 전달
    let columnInfo = isNaN(raw) ? raw : Number(raw);

    let result = target1.getColumnUseEditFormat(columnInfo);

    // 인덱스는 그대로, ID(문자열)는 따옴표로 표기
    let shown = (typeof columnInfo === 'string') ? "'" + columnInfo + "'" : columnInfo;
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnUseEditFormat(" + shown + ") -> 반환값: " + result);
}
